type Surface = "lobby" | "room" | "country" | "world" | "results" | "replay" | "admin";
const roles: InstitutionType[] = ["central_bank_governor", "economic_policy_minister", "trade_minister", "investment_resources_minister"];
const roleLabels: Record<InstitutionType | "country_captain", string> = { country_captain: "Country Captain", central_bank_governor: "Central Bank Governor", economic_policy_minister: "Economic Policy Minister", trade_minister: "Trade Minister", investment_resources_minister: "Investment & Resources Minister" };
const statusLabel = (status: string) => status.replaceAll("_", " ");
const number = (value: unknown) => Number(value ?? 0);

const fields: Record<InstitutionType, Array<{ key: string; label: string; min: number; max: number; step?: number }>> = {
  central_bank_governor: [{ key: "policyRate", label: "Policy rate (%)", min: 0, max: 15, step: 0.5 }, { key: "reserveRequirement", label: "Reserve requirement (%)", min: 0, max: 25 }, { key: "liquiditySupport", label: "Liquidity support", min: 0, max: 30 }, { key: "currencyIntervention", label: "Currency intervention", min: 0, max: 35 }, { key: "reserveDeployment", label: "Reserve deployment", min: 0, max: 35 }, { key: "emergencyFinancialSupport", label: "Emergency support", min: 0, max: 25 }],
  economic_policy_minister: [{ key: "governmentSpending", label: "Government spending", min: 0, max: 65 }, { key: "incomeTax", label: "Income tax (%)", min: 5, max: 50 }, { key: "businessTax", label: "Business tax (%)", min: 5, max: 50 }, { key: "welfare", label: "Welfare", min: 0, max: 40 }, { key: "employmentSupport", label: "Employment support", min: 0, max: 30 }, { key: "energySupport", label: "Energy support", min: 0, max: 40 }, { key: "fiscalReserve", label: "Fiscal reserve", min: 0, max: 35 }, { key: "publicServices", label: "Public services", min: 0, max: 30 }],
  trade_minister: [{ key: "tariff", label: "Tariff (%)", min: 0, max: 40 }, { key: "exportSupport", label: "Export support", min: 0, max: 30 }, { key: "importRestriction", label: "Import restriction", min: 0, max: 30 }, { key: "strategicSupplySpend", label: "Strategic supply", min: 0, max: 30 }, { key: "sanctionsIntensity", label: "Sanctions intensity", min: 0, max: 30 }],
  investment_resources_minister: [{ key: "infrastructure", label: "Infrastructure", min: 0, max: 50 }, { key: "researchAndDevelopment", label: "R&D", min: 0, max: 40 }, { key: "landAllocation", label: "Land allocation", min: 0, max: 50 }, { key: "energyCapacityInvestment", label: "Energy capacity", min: 0, max: 45 }, { key: "industrialZones", label: "Industrial zones", min: 0, max: 35 }, { key: "renewableInvestment", label: "Renewable investment", min: 0, max: 45 }, { key: "housingInvestment", label: "Housing investment", min: 0, max: 35 }],
};

function PageShell({ children }: { children: React.ReactNode }) { return <main className="mx-auto min-h-[68vh] max-w-[1440px] px-5 py-10 sm:px-8 lg:px-12">{children}</main>; }
function Notice({ children, error = false }: { children: React.ReactNode; error?: boolean }) { return <div className={`rounded-xl border px-4 py-3 text-sm ${error ? "border-[var(--red)] bg-[var(--red-soft)] text-[var(--red)]" : "border-[var(--accent)] bg-[var(--accent-soft)] text-[var(--accent)]"}`}>{children}</div>; }

function countryProfile(country: LeagueCompetitionCountry) {
  const snapshot = country.immutable_template_snapshot ?? {};
  const template = country.template;
  return {
    category: String(snapshot.category ?? template?.category ?? "Country profile"),
    tagline: String(snapshot.tagline ?? template?.tagline ?? template?.specialisation ?? ""),
    description: String(snapshot.description ?? template?.description ?? ""),
    strengths: [String((snapshot.config as Record<string, unknown> | undefined)?.primaryStrength ?? ""), String((snapshot.config as Record<string, unknown> | undefined)?.secondaryStrength ?? "")].filter(Boolean),
    vulnerabilities: [String((snapshot.config as Record<string, unknown> | undefined)?.primaryVulnerability ?? ""), String((snapshot.config as Record<string, unknown> | undefined)?.secondaryVulnerability ?? "")].filter(Boolean),
    strategies: (snapshot.viableStrategies ?? template?.viable_strategies ?? []) as string[],
    shares: (snapshot.sectorShares ?? template?.sector_shares ?? {}) as Record<string, number>,
    colour: String((snapshot.visualIdentity as Record<string, string> | undefined)?.primary ?? (template?.visual_identity?.primary ?? "var(--accent)")),
  };
}

function CountryPublicProfile({ country, compact = false }: { country: LeagueCompetitionCountry; compact?: boolean }) {
  const profile = countryProfile(country);
  const sectors = Object.entries(profile.shares).filter(([, value]) => Number(value) > 0).sort((left, right) => Number(right[1]) - Number(left[1])).slice(0, compact ? 2 : 3);
  return <div className="mt-4 rounded-xl border border-[var(--line)] bg-[var(--surface-subtle)] p-4"><div className="flex items-center gap-2"><span className="size-2 rounded-full" style={{ background: profile.colour }} /><p className="text-xs font-bold uppercase tracking-[.12em] text-[var(--accent)]">{profile.category}</p></div>{profile.tagline && <p className="mt-2 text-sm font-semibold">{profile.tagline}</p>}{!compact && profile.description && <p className="mt-2 text-xs leading-5 text-[var(--ink-muted)]">{profile.description}</p>}<div className="mt-3 flex flex-wrap gap-2">{sectors.map(([sector, share]) => <Badge key={sector}>{statusLabel(sector)} {Number(share)}%</Badge>)}</div>{!compact && <><div className="mt-3 grid gap-2 text-xs sm:grid-cols-2"><p><span className="font-bold">Strengths:</span> {profile.strengths.join(" · ") || "See country briefing after joining."}</p><p><span className="font-bold">Watch:</span> {profile.vulnerabilities.join(" · ") || "See country briefing after joining."}</p></div><p className="mt-3 text-xs text-[var(--ink-muted)]"><span className="font-bold text-[var(--ink)]">Viable paths:</span> {profile.strategies.slice(0, 2).join(" · ") || "Multiple policy strategies are available."}</p></>}</div>;
}

export function CompetitionDirectory() {
  const [competitions, setCompetitions] = useState<LeagueCompetition[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  useEffect(() => { void listLeagueCompetitions().then(setCompetitions).catch((caught) => setError(caught instanceof Error ? caught.message : "Could not load competitions.")).finally(() => setLoading(false)); }, []);
  const twelveNationCompetition = competitions.find((competition) => competition.scenario?.slug === "twelve-nations-interconnected-world");
  return <PageShell><div className="flex flex-wrap items-end justify-between gap-5"><div><Badge>League Simulation</Badge><h1 className="mt-3 text-4xl font-bold tracking-[-.05em]">Simulation World</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-[var(--ink-muted)]">Long-running, asynchronous country simulations. Country roles can work at any time; teachers settle each quarter manually after every country finalises.</p></div><Link href="/league/competitions/new" className="inline-flex h-10 items-center gap-2 rounded-lg bg-[var(--accent)] px-4 text-sm font-bold text-white"><Landmark size={16} /> Build competition</Link></div>{error && <div className="mt-6"><Notice error>{error}</Notice></div>}<div className="mt-8"><TwelveNationWorldOverview competitionId={twelveNationCompetition?.id} /></div><div className="mt-8 grid gap-4 lg:grid-cols-2">{loading ? <p className="text-sm text-[var(--ink-muted)]">Loading competitions…</p> : competitions.map((competition) => <Card key={competition.id} className="p-6"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-[var(--accent)]">{competition.scenario?.title ?? "League scenario"}</p><h2 className="mt-2 text-xl font-bold">{competition.name}</h2></div><Badge>Q{competition.current_round} editing open</Badge></div><p className="mt-3 text-sm leading-6 text-[var(--ink-muted)]">{competition.description || "A structured economic coordination competition."}</p><div className="mt-6 flex flex-wrap gap-2"><Link href={`/league/competitions/room?competition=${competition.id}`} className="text-sm font-bold text-[var(--accent)]">Open room <ArrowRight className="inline" size={14} /></Link><Link href={`/world?competition=${competition.id}`} className="text-sm font-bold text-[var(--ink-muted)]">World view</Link></div></Card>)}{!loading && !competitions.length && <Card className="p-7 text-sm text-[var(--ink-muted)]">No competition is visible yet. A platform administrator can create one from a published scenario.</Card>}</div></PageShell>;
}

export function CompetitionBuilder() {
  const { user, openAuth } = useAuth(); const router = useRouter(); const [contextRole, setContextRole] = useState(""); const [scenarios, setScenarios] = useState<LeagueScenario[]>([]); const [name, setName] = useState("New Global League"); const [description, setDescription] = useState(""); const [method, setMethod] = useState<"manual" | "random" | "balanced_random" | "snake_draft">("manual"); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const [error, setError] = useState("");
  useEffect(() => { if (!user) return; void Promise.all([getLeagueContext(user.id), listLeagueScenarios()]).then(([context, rows]) => { setContextRole(context.profile?.platform_role ?? ""); setScenarios(rows.filter((scenario) => scenario.status === "published")); }).catch((caught) => setError(caught instanceof Error ? caught.message : "Could not load builder data.")); }, [user]);
  const [scenarioId, setScenarioId] = useState(""); const selectedScenarioId = scenarioId || scenarios[0]?.id || "";
  async function create() { if (!user) return openAuth("sign-in"); if (contextRole !== "platform_admin") return setError("Only a platform administrator can create a competition."); if (!selectedScenarioId || !name.trim()) return setError("Choose a published scenario and give the competition a name."); setBusy(true); setError(""); try { const created = await createLeagueCompetition({ scenarioId: selectedScenarioId, name: name.trim(), description: description.trim(), assignmentMethod: method }); setMessage(`Competition created. Continue in its Lobby to assign schools, countries and institutions.`); router.push(`/league/competitions/room?competition=${created.id}`); } catch (caught) { setError(caught instanceof Error ? caught.message : "Could not create competition."); } finally { setBusy(false); } }
  return <PageShell><Badge>Competition Builder</Badge><h1 className="mt-3 text-4xl font-bold tracking-[-.05em]">Create a long-running world</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-[var(--ink-muted)]">There is no countdown or phase gate. Country roles can work whenever ready; directors manually settle a quarter only after every country finalises.</p>{error && <div className="mt-5"><Notice error>{error}</Notice></div>}{message && <div className="mt-5"><Notice>{message}</Notice></div>}<Card className="mt-8 max-w-2xl p-6"><label className="block text-sm font-bold">Published scenario<select value={selectedScenarioId} onChange={(event) => setScenarioId(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-3 text-sm">{scenarios.map((scenario) => <option key={scenario.id} value={scenario.id}>{scenario.title}</option>)}</select></label><label className="mt-5 block text-sm font-bold">Competition name<input value={name} onChange={(event) => setName(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-3 text-sm" /></label><label className="mt-5 block text-sm font-bold">Description<textarea value={description} onChange={(event) => setDescription(event.target.value)} className="mt-2 min-h-24 w-full rounded-lg border border-[var(--line)] bg-[var(--canvas)] p-3 text-sm" /></label><label className="mt-5 block text-sm font-bold">Country assignment<select value={method} onChange={(event) => setMethod(event.target.value as typeof method)} className="mt-2 h-10 w-full rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-3 text-sm"><option value="manual">Manual assignment</option><option value="random">Random assignment</option><option value="balanced_random">Balanced random assignment</option><option value="snake_draft">Snake draft (six schools, two countries)</option></select></label><Button className="mt-6" disabled={busy || !scenarios.length} onClick={create}>{busy && <LoaderCircle className="animate-spin" size={16} />} Create competition</Button>{!scenarios.length && <p className="mt-3 text-xs text-[var(--ink-muted)]">Create and publish a Scenario Studio scenario first.</p>}</Card></PageShell>;
}

function useCompetitionSnapshot() {
  const competitionId = useSearchParams()?.get("competition") ?? ""; const [snapshot, setSnapshot] = useState<CompetitionSnapshot | null>(null); const [loading, setLoading] = useState(Boolean(competitionId)); const [error, setError] = useState("");
  const refresh = useCallback(async () => { if (!competitionId) return; setLoading(true); try { setSnapshot(await getLeagueCompetition(competitionId)); setError(""); } catch (caught) { setError(caught instanceof Error ? caught.message : "Could not refresh this competition."); } finally { setLoading(false); } }, [competitionId]);
  useEffect(() => { queueMicrotask(() => { void refresh(); }); }, [refresh]);
  useEffect(() => { if (!competitionId) return; const channel = subscribeToLeagueCompetition(competitionId, () => void refresh()); return () => unsubscribeLeagueCompetition(channel); }, [competitionId, refresh]);
  return { competitionId, snapshot, loading, error, refresh };
}

export function CompetitionSurface({ surface }: { surface: Surface }) {
  const { user, openAuth } = useAuth(); const { competitionId, snapshot, loading, error, refresh } = useCompetitionSnapshot(); const [platformRole, setPlatformRole] = useState("");
  useEffect(() => { if (!user) return; void getLeagueContext(user.id).then((context) => setPlatformRole(context.profile?.platform_role ?? "")); }, [user]);
  if (!competitionId) return <PageShell><Notice>Choose a competition from <Link href="/league/competitions" className="font-bold underline">Competitions</Link>.</Notice></PageShell>;
  if (loading && !snapshot) return <PageShell><p className="text-sm text-[var(--ink-muted)]">Loading competition…</p></PageShell>;
  if (error) return <PageShell><Notice error>{error}</Notice><Button className="mt-4" variant="secondary" onClick={() => void refresh()}>Retry</Button></PageShell>;
  if (!snapshot) return <PageShell><Notice error>This competition is not available to your account.</Notice></PageShell>;
  const myRoles = snapshot.roles.filter((role) => role.user_id === user?.id); const myCountry = snapshot.countries.find((country) => myRoles.some((role) => role.country_id === country.id)) ?? null; const isAdmin = platformRole === "platform_admin";
  const nav = [{ href: `/lobby?competition=${competitionId}`, label: "Lobby" }, { href: `/room?competition=${competitionId}`, label: "Room" }, { href: `/country?competition=${competitionId}`, label: "Country" }, { href: `/world?competition=${competitionId}`, label: "World" }, { href: `/results?competition=${competitionId}`, label: "Results" }, { href: `/replay?competition=${competitionId}`, label: "Replay" }];
  return <PageShell><div className="flex flex-wrap items-center justify-between gap-4 border-b border-[var(--line)] pb-5"><div><div className="flex gap-3"><Link href="/league" className="text-xs font-bold text-[var(--accent)]">← League Home</Link><Link href="/league/competitions" className="text-xs font-bold text-[var(--ink-muted)]">Competitions</Link></div><h1 className="mt-1 text-3xl font-bold tracking-[-.05em]">{snapshot.competition.name}</h1><p className="mt-1 text-sm text-[var(--ink-muted)]">Quarter {snapshot.competition.current_round} · country editing is open</p></div><div className="flex items-center gap-2"><Badge>{isAdmin ? "Teacher administrator" : myCountry ? myCountry.display_name : "Public observer"}</Badge><Button size="sm" variant="secondary" onClick={() => void refresh()}><RefreshCw size={14} /> Refresh</Button></div></div><nav className="scroll-rail mt-4 flex overflow-x-auto gap-1 pb-1">{nav.map((item) => <Link key={item.href} href={item.href} className={`shrink-0 rounded-lg px-3 py-2 text-xs font-bold ${item.label.toLowerCase() === surface ? "bg-[var(--accent)] text-white" : "text-[var(--ink-muted)] hover:bg-[var(--surface-subtle)]"}`}>{item.label}</Link>)}{isAdmin && <Link href={`/admin?competition=${competitionId}`} className={`shrink-0 rounded-lg px-3 py-2 text-xs font-bold ${surface === "admin" ? "bg-[var(--accent)] text-white" : "text-[var(--ink-muted)] hover:bg-[var(--surface-subtle)]"}`}>Admin</Link>}</nav><div className="mt-7">{surface === "lobby" && <Lobby snapshot={snapshot} userId={user?.id ?? ""} signedIn={Boolean(user)} openAuth={openAuth} refresh={refresh} />}{surface === "room" && <Room snapshot={snapshot} myCountry={myCountry} />}{surface === "country" && <CountryWorkspace snapshot={snapshot} myCountry={myCountry} myRoles={myRoles} userId={user?.id ?? ""} openAuth={openAuth} refresh={refresh} isAdmin={isAdmin} />}{surface === "world" && <WorldView snapshot={snapshot} />}{surface === "results" && <ResultsView snapshot={snapshot} replay={false} />}{surface === "replay" && <ResultsView snapshot={snapshot} replay />}{surface === "admin" && <AdminPanel snapshot={snapshot} isAdmin={isAdmin} refresh={refresh} />}</div></PageShell>;
}

function Lobby({ snapshot, userId, signedIn, openAuth, refresh }: { snapshot: CompetitionSnapshot; userId: string; signedIn: boolean; openAuth: (mode?: "sign-in" | "sign-up") => void; refresh: () => Promise<void> }) {
  const [message, setMessage] = useState(""); const [error, setError] = useState("");
  const openIndividualRegistration = Boolean(snapshot.competition.config.openIndividualRegistration);
  async function claim(country: LeagueCompetitionCountry, role: InstitutionType | "country_captain") { if (!signedIn) return openAuth("sign-in"); try { await claimCompetitionRole(snapshot.competition.id, country.id, role, role === "country_captain"); setMessage(`${roleLabels[role]} claimed for ${country.display_name}.`); await refresh(); } catch (caught) { setError(caught instanceof Error ? caught.message : "This role could not be claimed."); } }
  return <><div className="grid gap-4 lg:grid-cols-[1.15fr_.85fr]"><Card className="p-6"><p className="text-xs font-bold uppercase tracking-[.14em] text-[var(--accent)]">Competition lobby</p><h2 className="mt-2 text-2xl font-bold">Build each country at its own pace.</h2><p className="mt-3 text-sm leading-6 text-[var(--ink-muted)]">{openIndividualRegistration ? "This world is open to registered individuals. Claim an available country role at any time; teachers can still organise teams and assign schools later." : "A school team owns one country. Members can hold more than one institution role, but each of the four institutional positions must be filled before the country can finalise."}</p><div className="mt-5 flex flex-wrap gap-2">{snapshot.rounds.map((round) => <Badge key={round.id}>Q{round.round_number}: {round.published_at ? "released" : round.round_number === snapshot.competition.current_round ? "editing open" : "upcoming"}</Badge>)}</div></Card><Card className="p-6"><p className="font-bold">Public visibility</p><p className="mt-2 text-sm leading-6 text-[var(--ink-muted)]">Country profiles, world indicators and published rankings are visible to signed-in users. Numerical policy sensitivities, drafts and unreleased country packages remain private to the relevant country roles and directors.</p><Link href={`/world?competition=${snapshot.competition.id}`} className="mt-5 inline-block text-sm font-bold text-[var(--accent)]">Open the world map →</Link></Card></div>{error && <div className="mt-4"><Notice error>{error}</Notice></div>}{message && <div className="mt-4"><Notice>{message}</Notice></div>}<div className="mt-6 grid gap-4 lg:grid-cols-2">{snapshot.countries.map((country) => { const countryRoles = snapshot.roles.filter((role) => role.country_id === country.id); const occupied = new Set(countryRoles.map((role) => role.role_type)); const mine = countryRoles.filter((role) => role.user_id === userId); return <Card key={country.id} className="p-6"><div className="flex items-start justify-between gap-3"><div><h3 className="text-xl font-bold">{country.display_name}</h3><p className="mt-1 text-xs font-bold uppercase tracking-[.12em] text-[var(--accent)]">{country.template?.specialisation ?? "Country profile"}</p></div><Badge>{country.team?.name ?? (openIndividualRegistration ? "Open roles" : "Awaiting team")}</Badge></div><p className="mt-4 text-sm text-[var(--ink-muted)]">{country.school?.name ?? (openIndividualRegistration ? "Individual registration is open." : "A director must assign an approved school team.")}</p><CountryPublicProfile country={country} compact /><div className="mt-5 grid gap-2">{(["country_captain", ...roles] as const).map((role) => { const holder = countryRoles.find((item) => item.role_type === role); return <div key={role} className="flex items-center justify-between rounded-lg bg-[var(--surface-subtle)] px-3 py-2 text-xs"><span className="font-bold">{roleLabels[role]}</span>{holder ? <span className="text-[var(--ink-muted)]">{holder.user_id === userId ? "You" : holder.profile?.display_name ?? "Claimed"}</span> : <Button size="sm" disabled={(!openIndividualRegistration && !country.team) || occupied.has(role)} onClick={() => void claim(country, role)}>Claim</Button>}</div>; })}</div>{mine.length > 0 && <Link href={`/country?competition=${snapshot.competition.id}`} className="mt-5 inline-block text-sm font-bold text-[var(--accent)]">Enter country workspace →</Link>}</Card>; })}</div></>;
}

function Room({ snapshot, myCountry }: { snapshot: CompetitionSnapshot; myCountry: LeagueCompetitionCountry | null }) { return <div className="grid gap-4 lg:grid-cols-[1.2fr_.8fr]"><Card className="p-6"><Badge>Integrated country room</Badge><h2 className="mt-3 text-2xl font-bold">{myCountry ? `${myCountry.display_name} coordination room` : "Observer room"}</h2><p className="mt-3 text-sm leading-6 text-[var(--ink-muted)]">This room brings together the four institutions, the country captain and international agreements. It never runs an automatic deadline: teachers manually settle only after all country submissions are finalised.</p><div className="mt-6 grid gap-2 sm:grid-cols-2">{roles.map((role) => <div key={role} className="rounded-lg border border-[var(--line)] p-3 text-sm"><p className="font-bold">{roleLabels[role]}</p><p className="mt-1 text-xs text-[var(--ink-muted)]">Own domain, shared resources, visible coordination warnings.</p></div>)}</div></Card><Card className="p-6"><p className="font-bold">Current quarter</p><p className="mt-2 text-3xl font-bold">Q{snapshot.competition.current_round}</p><p className="mt-2 text-sm text-[var(--ink-muted)]">Country editing is open</p><Link href={`/country?competition=${snapshot.competition.id}`} className="mt-6 inline-flex h-10 items-center rounded-lg bg-[var(--accent)] px-4 text-sm font-bold text-white">Open decisions</Link></Card><Card className="p-6 lg:col-span-2"><p className="font-bold">Event timeline</p><div className="mt-4 space-y-3">{snapshot.events.slice(0, 8).map((event) => <div key={event.id} className="flex gap-3 text-sm"><span className="mt-1 size-2 shrink-0 rounded-full bg-[var(--accent)]" /><p><span className="font-bold capitalize">{statusLabel(event.event_type)}</span><span className="ml-2 text-[var(--ink-muted)]">{new Date(event.created_at).toLocaleString()}</span></p></div>)}{!snapshot.events.length && <p className="text-sm text-[var(--ink-muted)]">The durable event history will appear after teachers settle and release a quarter.</p>}</div></Card></div>; }

function CountryWorkspace({ snapshot, myCountry, myRoles, userId, openAuth, refresh, isAdmin }: { snapshot: CompetitionSnapshot; myCountry: LeagueCompetitionCountry | null; myRoles: CompetitionSnapshot["roles"]; userId: string; openAuth: (mode?: "sign-in" | "sign-up") => void; refresh: () => Promise<void>; isAdmin: boolean }) {
  const [selectedCountryId, setSelectedCountryId] = useState(myCountry?.id ?? snapshot.countries[0]?.id ?? "");
  const country = isAdmin ? snapshot.countries.find((item) => item.id === selectedCountryId) ?? snapshot.countries[0] ?? null : myCountry;
  const currentRound = snapshot.rounds.find((round) => round.round_number === snapshot.competition.current_round);
  const institutionRoles = isAdmin ? roles : myRoles.filter((role) => role.country_id === country?.id && roles.includes(role.role_type as InstitutionType)).map((role) => role.role_type as InstitutionType);
  const captain = isAdmin || myRoles.some((role) => role.country_id === country?.id && (role.role_type === "country_captain" || role.is_captain));
  if (!userId) return <Card className="p-6"><p className="font-bold">Sign in to open a country workspace.</p><Button className="mt-4" onClick={() => openAuth("sign-in")}>Sign in</Button></Card>;
  if (!country) return <Card className="p-6"><p className="font-bold">You do not currently hold a country role.</p><p className="mt-2 text-sm text-[var(--ink-muted)]">Claim an available role from the Lobby after your team has been assigned.</p><Link className="mt-4 inline-block text-sm font-bold text-[var(--accent)]" href={`/lobby?competition=${snapshot.competition.id}`}>Return to Lobby →</Link></Card>;
  if (!currentRound) return <Notice error>The active competition round is missing.</Notice>;
  return <div className="grid gap-5 xl:grid-cols-[1fr_.34fr]"><div><div className="flex flex-wrap items-center justify-between gap-3"><div><Badge>{country.display_name}</Badge><h2 className="mt-2 text-2xl font-bold">Institution decisions</h2></div><Badge>Editing open</Badge></div>{isAdmin && <Card className="mt-5 border-[var(--accent)] bg-[var(--accent-soft)] p-4 text-sm"><p className="font-bold">Teacher administrator control</p><p className="mt-1 text-[var(--ink-muted)]">Select any country and operate all four institution panels. Locked decisions remain immutable for this round.</p><label className="mt-3 block text-xs font-bold">Country<select value={country.id} onChange={(event) => setSelectedCountryId(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-3 text-sm">{snapshot.countries.map((item) => <option key={item.id} value={item.id}>{item.display_name}</option>)}</select></label></Card>}{institutionRoles.length ? institutionRoles.map((role) => <InstitutionEditor key={role} snapshot={snapshot} country={country} roundId={currentRound.id} role={role} refresh={refresh} />) : <Card className="mt-5 p-6 text-sm text-[var(--ink-muted)]">Your country role is Captain only. You can review locked work and finalise once all four institution holders lock their own draft.</Card>}<Finalisation snapshot={snapshot} country={country} roundId={currentRound.id} captain={captain} refresh={refresh} /></div><div className="space-y-5"><AgreementPanel snapshot={snapshot} country={country} roles={institutionRoles} refresh={refresh} isAdmin={isAdmin} /><Card className="p-5"><p className="font-bold">Coordination rule</p><p className="mt-2 text-sm leading-6 text-[var(--ink-muted)]">A captain cannot overwrite any institution’s locked decision. The final submission is assembled by the database from all four locked drafts.</p></Card></div></div>;
}

function InstitutionEditor({ snapshot, country, roundId, role, refresh }: { snapshot: CompetitionSnapshot; country: LeagueCompetitionCountry; roundId: string; role: InstitutionType; refresh: () => Promise<void> }) {
  const existing = snapshot.drafts.find((draft) => draft.round_id === roundId && draft.country_id === country.id && draft.institution_type === role); const initial = useMemo(() => ({ ...(defaultInstitutionDecisions()[role] as Record<string, number>), ...(existing?.draft_state ?? {}) }) as Record<string, number>, [existing?.draft_state, role]); const [draft, setDraft] = useState(initial); const [dirty, setDirty] = useState(false); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const [error, setError] = useState(""); const initialized = useRef(false);
  useEffect(() => { queueMicrotask(() => { setDraft(initial); setDirty(false); initialized.current = true; }); }, [initial]);
  const all = useMemo(() => { const values = defaultInstitutionDecisions() as unknown as Record<InstitutionType, Record<string, number>>; for (const item of snapshot.drafts.filter((draftItem) => draftItem.round_id === roundId && draftItem.country_id === country.id)) values[item.institution_type] = { ...values[item.institution_type], ...(item.draft_state as Record<string, number>) }; values[role] = { ...values[role], ...draft }; return values; }, [country.id, draft, role, roundId, snapshot.drafts]);
  const simulation = country.template?.slug && TWELVE_COUNTRY_WORLD_SCENARIO.countryTemplates.some((template) => template.slug === country.template?.slug) ? createWorldState(TWELVE_COUNTRY_WORLD_SCENARIO) : createWorldState(); const template = simulation.countries.find((item) => item.templateId === country.template?.slug || item.templateId === country.country_template_id) ?? simulation.countries[0]; const constraints = detectInstitutionConstraints({ ...template, countryId: country.id, countryName: country.display_name }, all as never);
  const save = useCallback(async (silent = false) => { if (existing?.status === "locked") return; setBusy(true); try { await saveInstitutionDraft({ competitionId: snapshot.competition.id, roundId, countryId: country.id, institution: role, draftState: draft }); setDirty(false); if (!silent) setMessage("Draft saved."); await refresh(); } catch (caught) { setError(caught instanceof Error ? caught.message : "Draft could not be saved."); } finally { setBusy(false); } }, [country.id, draft, existing?.status, refresh, role, roundId, snapshot.competition.id]);
  useEffect(() => { if (!initialized.current || !dirty || existing?.status === "locked") return; const timeout = window.setTimeout(() => { void save(true); }, 1400); return () => window.clearTimeout(timeout); }, [dirty, existing?.status, save]); // intentional debounced autosave
  async function lock() { try { let draftId = existing?.id; if (!draftId) { await save(false); const fresh = await getLeagueCompetition(snapshot.competition.id); draftId = fresh?.drafts.find((item) => item.round_id === roundId && item.country_id === country.id && item.institution_type === role)?.id; } if (!draftId) throw new Error("Save the draft before locking it."); await lockInstitutionDraft(draftId); setMessage("Institution draft locked. It is now immutable to other roles and to the captain."); await refresh(); } catch (caught) { setError(caught instanceof Error ? caught.message : "Draft could not be locked."); } }
  return <Card className="mt-5 p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-bold">{roleLabels[role]}</h3><p className="mt-1 text-xs text-[var(--ink-muted)]">Autosaves after 1.4 seconds of inactivity. A lock is deliberate and irreversible for this round.</p></div><Badge>{existing?.status ?? "draft"}</Badge></div>{error && <div className="mt-3"><Notice error>{error}</Notice></div>}{message && <div className="mt-3"><Notice>{message}</Notice></div>}<div className="mt-5 grid gap-4 sm:grid-cols-2">{fields[role].map((field) => <label key={field.key} className="block rounded-lg bg-[var(--surface-subtle)] p-3 text-xs font-bold">{field.label}<span className="float-right text-[var(--accent)]">{number(draft[field.key]).toFixed(field.step === 0.5 ? 1 : 0)}</span><input type="range" min={field.min} max={field.max} step={field.step ?? 1} value={number(draft[field.key])} disabled={existing?.status === "locked"} onChange={(event) => { setDraft((current) => ({ ...current, [field.key]: Number(event.target.value) })); setDirty(true); setMessage(""); }} className="mt-3 w-full accent-[var(--accent)]" /></label>)}</div><div className="mt-5 grid gap-2 rounded-lg border border-[var(--line)] p-3 text-xs"><p className="font-bold">Shared resources · fiscal outlook</p>{constraints.blocking.length ? <p className="text-[var(--red)]">{constraints.blocking.join(" ")}</p> : constraints.fiscalDeficit > 0 ? <p className="text-[var(--ink-muted)]">Planned deficit: {constraints.fiscalDeficit.toFixed(0)} points. It remains permitted; expected next-quarter fiscal space is {constraints.nextQuarterFiscalCapacity.toFixed(0)}.</p> : <p className="text-[var(--accent)]">No planned deficit. Expected next-quarter fiscal space is {constraints.nextQuarterFiscalCapacity.toFixed(0)}.</p>}{constraints.warnings.map((warning) => <p key={warning} className="text-[var(--ink-muted)]">Note: {warning}</p>)}</div><div className="mt-5 flex flex-wrap gap-2"><Button disabled={busy || existing?.status === "locked"} onClick={() => void save()}>{busy && <LoaderCircle className="animate-spin" size={15} />} Save now</Button><Button variant="secondary" disabled={busy || existing?.status === "locked" || constraints.blocking.length > 0} onClick={() => void lock()}><Lock size={14} /> Lock decision</Button></div></Card>;
}

function Finalisation({ snapshot, country, roundId, captain, refresh }: { snapshot: CompetitionSnapshot; country: LeagueCompetitionCountry; roundId: string; captain: boolean; refresh: () => Promise<void> }) { const locked = snapshot.drafts.filter((draft) => draft.round_id === roundId && draft.country_id === country.id && draft.status === "locked").length; const [message, setMessage] = useState(""); const [error, setError] = useState(""); async function finish() { try { await finaliseCountrySubmission({ competitionId: snapshot.competition.id, roundId, countryId: country.id }); setMessage("Country package finalised from all locked institutional drafts."); await refresh(); } catch (caught) { setError(caught instanceof Error ? caught.message : "Country package could not be finalised."); } } return <Card className="mt-5 p-5"><div className="flex flex-wrap items-center justify-between gap-4"><div><p className="font-bold">Country submission</p><p className="mt-1 text-sm text-[var(--ink-muted)]">{locked}/4 institutional drafts locked.</p></div>{captain && <Button disabled={locked !== 4} onClick={() => void finish()}><CheckCircle2 size={15} /> Finalise country</Button>}</div>{error && <div className="mt-3"><Notice error>{error}</Notice></div>}{message && <div className="mt-3"><Notice>{message}</Notice></div>}</Card>; }

function AgreementPanel({ snapshot, country, roles: heldRoles, refresh, isAdmin }: { snapshot: CompetitionSnapshot; country: LeagueCompetitionCountry; roles: InstitutionType[]; refresh: () => Promise<void>; isAdmin: boolean }) { const [type, setType] = useState<AgreementType>("trade"); const [partner, setPartner] = useState(""); const [message, setMessage] = useState(""); const [error, setError] = useState(""); const required = agreementRequiresRoles(type); const effectiveRoles = isAdmin ? roles : heldRoles; async function approve(participantId: string) { try { await approveAgreement(participantId, "approved"); setMessage("Agreement approval recorded. It activates in the next eligible clearing only after every required approval."); await refresh(); } catch (caught) { setError(caught instanceof Error ? caught.message : "Approval failed."); } } return <Card className="p-5"><p className="font-bold">International agreements</p><p className="mt-2 text-xs leading-5 text-[var(--ink-muted)]">Trade, energy supply and technology partnership are enabled initially. Other agreement types remain extensible in the data model.</p>{error && <div className="mt-3"><Notice error>{error}</Notice></div>}{message && <div className="mt-3"><Notice>{message}</Notice></div>}<div className="mt-4 flex gap-2"><select value={type} onChange={(event) => setType(event.target.value as AgreementType)} className="h-9 min-w-0 flex-1 rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-2 text-xs"><option value="trade">Trade</option><option value="energy_supply">Energy supply</option><option value="technology_partnership">Technology partnership</option></select><select value={partner} onChange={(event) => setPartner(event.target.value)} className="h-9 min-w-0 flex-1 rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-2 text-xs"><option value="">Partner</option>{snapshot.countries.filter((item) => item.id !== country.id).map((item) => <option key={item.id} value={item.id}>{item.display_name}</option>)}</select></div><p className="mt-2 text-xs text-[var(--ink-muted)]">Required: {required.map((role) => roleLabels[role]).join(" + ")}</p><Button size="sm" className="mt-3" disabled={!partner || !required.some((role) => effectiveRoles.includes(role))} onClick={async () => { try { const { proposeAgreement } = await import("@/lib/supabase/league-infrastructure"); await proposeAgreement({ competitionId: snapshot.competition.id, proposerCountryId: country.id, type, terms: { tariffReduction: type === "trade" ? 3 : 0, duration: 1 }, participantCountryIds: [partner], requiredRoles: required, startsRound: Math.min(3, snapshot.competition.current_round + 1), endsRound: 3 }); setMessage("Agreement proposed. Required institutions must approve it."); await refresh(); } catch (caught) { setError(caught instanceof Error ? caught.message : "Agreement could not be proposed."); } }}>Propose</Button><div className="mt-5 space-y-2">{snapshot.agreements.map((agreement) => <div key={agreement.id} className="rounded-lg border border-[var(--line)] p-3 text-xs"><p className="font-bold capitalize">{statusLabel(agreement.agreement_type)} · {statusLabel(agreement.status)}</p>{agreement.participants?.filter((participant) => participant.country_id === country.id && effectiveRoles.includes(participant.required_role)).map((participant) => <Button key={participant.id} size="sm" className="mt-2" variant="secondary" disabled={participant.approval_status === "approved"} onClick={() => void approve(participant.id)}>Approve as {roleLabels[participant.required_role]}</Button>)}</div>)}{!snapshot.agreements.length && <p className="text-xs text-[var(--ink-muted)]">No agreements yet.</p>}</div></Card>; }

function WorldView({ snapshot }: { snapshot: CompetitionSnapshot }) {
  const latest = snapshot.results[0];
  const state = latest?.state_after as { markets?: Array<{ commodity: string; globalPrice: number; totalSupply: number; totalDemand: number }>; globalIndicators?: Record<string, number> } | undefined;
  const indicators = state?.globalIndicators ?? {};
  return <div className="grid gap-4 lg:grid-cols-[1.25fr_.75fr]"><Card className="p-6"><Badge>Public world dashboard</Badge><h2 className="mt-3 text-2xl font-bold">Interconnected world economy</h2><p className="mt-2 text-sm text-[var(--ink-muted)]">Commodity prices clear only after all {snapshot.countries.length} countries finalise. This is a released-results dashboard, not a live market order book.</p><div className="mt-6 grid gap-3 sm:grid-cols-2">{(state?.markets ?? []).map((market) => <div key={market.commodity} className="rounded-lg bg-[var(--surface-subtle)] p-4"><p className="text-xs font-bold uppercase tracking-[.12em] text-[var(--ink-muted)]">{statusLabel(market.commodity)}</p><p className="mt-2 text-2xl font-bold">{market.globalPrice.toFixed(1)}</p><p className="mt-1 text-xs text-[var(--ink-muted)]">Supply {market.totalSupply.toFixed(0)} · demand {market.totalDemand.toFixed(0)}</p></div>)}{!state?.markets?.length && <p className="text-sm text-[var(--ink-muted)]">The world dashboard will populate after the first processed round.</p>}</div></Card><Card className="p-6"><p className="font-bold">Global indicators</p><div className="mt-4 space-y-3">{Object.entries(indicators).map(([key, value]) => <div key={key} className="flex justify-between text-sm"><span className="capitalize text-[var(--ink-muted)]">{statusLabel(key)}</span><strong>{number(value).toFixed(1)}</strong></div>)}</div></Card><Card className="p-6 lg:col-span-2"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="font-bold">Country profiles</p><p className="mt-1 text-sm text-[var(--ink-muted)]">Public comparative advantage, vulnerabilities and viable pathways. Detailed numerical modifiers remain private.</p></div><Badge>{snapshot.countries.length} countries</Badge></div><div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{snapshot.countries.map((country) => <div key={country.id}><p className="text-sm font-bold">{country.display_name}</p><CountryPublicProfile country={country} compact /></div>)}</div></Card><Card className="p-6 lg:col-span-2"><p className="font-bold">Latest published trade links</p><div className="scroll-slim mt-4 overflow-x-auto"><table className="min-w-full text-left text-xs"><thead className="text-[var(--ink-muted)]"><tr><th className="pb-2">Exporter</th><th className="pb-2">Importer</th><th className="pb-2">Commodity</th><th className="pb-2">Quantity</th><th className="pb-2">Tariff</th></tr></thead><tbody>{snapshot.tradeFlows.slice(0, 20).map((flow) => <tr key={flow.id} className="border-t border-[var(--line)]"><td className="py-2">{snapshot.countries.find((country) => country.id === flow.exporter_country_id)?.display_name}</td><td className="py-2">{snapshot.countries.find((country) => country.id === flow.importer_country_id)?.display_name}</td><td className="py-2">{statusLabel(flow.commodity)}</td><td className="py-2">{Number(flow.quantity).toFixed(1)}</td><td className="py-2">{Number(flow.tariff).toFixed(1)}%</td></tr>)}</tbody></table></div></Card></div>;
}

function ResultsView({ snapshot, replay }: { snapshot: CompetitionSnapshot; replay: boolean }) {
  const [roundId, setRoundId] = useState(snapshot.rounds.filter((round) => round.published_at).at(-1)?.id ?? snapshot.results[0]?.round_id ?? ""); const results = snapshot.results.filter((item) => !roundId || item.round_id === roundId).sort((left, right) => number(right.scores.total) - number(left.scores.total)); const exportCsv = () => { const rows = [["exporter", "importer", "commodity", "quantity", "price", "tariff"], ...snapshot.tradeFlows.filter((flow) => !roundId || flow.round_id === roundId).map((flow) => [snapshot.countries.find((country) => country.id === flow.exporter_country_id)?.display_name ?? flow.exporter_country_id, snapshot.countries.find((country) => country.id === flow.importer_country_id)?.display_name ?? flow.importer_country_id, flow.commodity, flow.quantity, flow.base_price, flow.tariff])]; const url = URL.createObjectURL(new Blob([rows.map((row) => row.join(",")).join("\n")], { type: "text/csv" })); const link = document.createElement("a"); link.href = url; link.download = "econmind-trade-matrix.csv"; link.click(); URL.revokeObjectURL(url); };
  return <><div className="flex flex-wrap items-end justify-between gap-4"><div><Badge>{replay ? "Replay" : "Released results"}</Badge><h2 className="mt-2 text-2xl font-bold">{replay ? "Decision replay" : "Leaderboard"}</h2></div><div className="flex gap-2"><select value={roundId} onChange={(event) => setRoundId(event.target.value)} className="h-10 rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-3 text-sm">{snapshot.rounds.filter((round) => round.published_at || round.id === roundId).map((round) => <option key={round.id} value={round.id}>Quarter {round.round_number}</option>)}</select><Button variant="secondary" onClick={exportCsv}><Download size={15} /> Trade CSV</Button></div></div><div className="mt-6 grid gap-4 lg:grid-cols-2">{results.map((result, index) => { const country = snapshot.countries.find((item) => item.id === result.country_id); const profile = country ? countryProfile(country) : null; const rolesUsed = Object.keys(result.decisions ?? {}).length; return <Card key={result.id} className="p-6"><div className="flex justify-between gap-3"><p className="text-lg font-bold">#{index + 1} {country?.display_name ?? "Country"}</p><Badge>{number(result.scores.total).toFixed(1)} pts</Badge></div><div className="mt-4 grid grid-cols-2 gap-2 text-xs">{Object.entries(result.scores).filter(([key]) => key !== "roleScores" && key !== "total").map(([key, value]) => <div key={key} className="rounded bg-[var(--surface-subtle)] p-2"><span className="block text-[var(--ink-muted)]">{statusLabel(key)}</span><strong>{number(value).toFixed(1)}</strong></div>)}</div>{replay && <div className="mt-4 space-y-3 text-sm text-[var(--ink-muted)]"><div className="rounded-lg bg-[var(--surface-subtle)] p-3"><p className="font-bold text-[var(--ink)]">Structural conditions</p><p className="mt-1">{profile?.category ?? "Country structure"} · {profile?.tagline || "Opening country structure shaped the available paths."}</p></div><div className="rounded-lg bg-[var(--surface-subtle)] p-3"><p className="font-bold text-[var(--ink)]">This quarter’s policy package</p><p className="mt-1">{rolesUsed} institutional decision set{rolesUsed === 1 ? "" : "s"} entered the deterministic settlement. Taxes affect fiscal capacity in the following quarter; deficits remain permitted but raise later debt and confidence risk.</p></div><p>{(result.explanations.domesticOutcome as string[] | undefined)?.[0]}</p><p>{(result.explanations.internationalTransmission as string[] | undefined)?.[0]}</p><p className="font-semibold text-[var(--ink)]">Forward risk: {String(result.explanations.forwardRisk ?? "—")}</p></div>}</Card>; })}{!results.length && <Card className="p-6 text-sm text-[var(--ink-muted)]">Results appear here only after a director publishes a processed round.</Card>}</div></>;
}

function AdminPanel({ snapshot, isAdmin, refresh }: { snapshot: CompetitionSnapshot; isAdmin: boolean; refresh: () => Promise<void> }) {
  const [teams, setTeams] = useState<Array<{ id: string; name: string; school_id: string }>>([]);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const currentRound = snapshot.rounds.find((round) => round.round_number === snapshot.competition.current_round);
  useEffect(() => { if (!isAdmin) return; void listLeagueSchools().then(async (schools) => { const groups = await Promise.all(schools.filter((school) => school.status === "approved").map((school) => listSchoolTeams(school.id))); setTeams(groups.flat().map((team) => ({ id: team.id, name: team.name, school_id: team.school_id }))); }).catch((caught) => setError(caught instanceof Error ? caught.message : "Could not load approved teams.")); }, [isAdmin]);
  if (!isAdmin) return <Notice error>Platform administrator access is required for competition control.</Notice>;
  async function action(work: () => Promise<unknown>, success: string) { try { await work(); setMessage(success); await refresh(); } catch (caught) { setError(caught instanceof Error ? caught.message : "Action failed."); } }
  async function applyBalancedPlan() { const plan = planBalancedCountryAssignment(snapshot.countries, teams); if (!plan.length) throw new Error("There are no unassigned countries or approved teams available."); for (const assignment of plan) await assignCompetitionCountry(assignment); }
  return <div className="space-y-5">{error && <Notice error>{error}</Notice>}{message && <Notice>{message}</Notice>}<Card className="p-6"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="font-bold">Country assignment</p><p className="mt-2 text-sm text-[var(--ink-muted)]">Manual choices remain available. The deterministic balanced plan distributes score, category and commodity exposure before writing any assignments.</p></div><Button size="sm" variant="secondary" disabled={!teams.length || !snapshot.countries.some((country) => !country.assigned_team_id)} onClick={() => { if (window.confirm("Assign all currently open countries with the balanced plan?")) void action(applyBalancedPlan, "Balanced country assignments applied."); }}><Sparkles size={14} /> Apply balanced plan</Button></div><div className="mt-4 grid gap-3">{snapshot.countries.map((country) => <div key={country.id} className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-[var(--line)] p-3"><div><strong className="text-sm">{country.display_name}</strong><p className="text-xs text-[var(--ink-muted)]">{country.team?.name ?? "No team assigned"}</p></div><select value={country.assigned_team_id ?? ""} onChange={(event) => { const team = teams.find((item) => item.id === event.target.value); if (team && window.confirm(`Assign ${team.name} to ${country.display_name}?`)) void action(() => assignCompetitionCountry({ countryId: country.id, schoolId: team.school_id, teamId: team.id }), `${country.display_name} assigned to ${team.name}.`); }} className="h-9 max-w-60 rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-2 text-xs"><option value="">Assign approved team…</option>{teams.map((team) => <option key={team.id} value={team.id}>{team.name}</option>)}</select></div>)}</div></Card><RoleControls snapshot={snapshot} refresh={refresh} /><Card className="p-6"><Badge>Teacher settlement</Badge><p className="mt-3 font-bold">Settle and release a quarter</p><p className="mt-2 text-sm text-[var(--ink-muted)]">Country work is always open. When all {snapshot.countries.length} countries have finalised, settle the quarter manually; after reviewing it, release results to open the next quarter automatically.</p><div className="mt-4 flex flex-wrap gap-2"><Button disabled={!currentRound} onClick={() => { if (currentRound && window.confirm("Run deterministic world clearing for this completed quarter?")) void action(() => processLeagueWorldRound(snapshot.competition.id, currentRound.id), "World clearing completed. Review then release the results."); }}><ShieldCheck size={15} /> Settle this quarter</Button><Button variant="secondary" disabled={!currentRound || currentRound.status !== "processed"} onClick={() => { if (currentRound && window.confirm("Release this processed quarter and open the next one?")) void action(() => publishCompetitionRound(snapshot.competition.id, currentRound.id), "Results released. The next quarter is now open."); }}>Release results</Button><Button variant="danger" disabled={!currentRound || currentRound.status !== "processing"} onClick={() => { if (currentRound && window.confirm("Mark this processing attempt for recovery?")) void action(() => recoverWorldProcessing(snapshot.competition.id, currentRound.id, "Teacher recovery action"), "Round marked failed and ready for controlled recovery."); }}>Recover</Button></div></Card></div>;
}

function RoleControls({ snapshot, refresh }: { snapshot: CompetitionSnapshot; refresh: () => Promise<void> }) { const [countryId, setCountryId] = useState(snapshot.countries[0]?.id ?? ""); const [role, setRole] = useState<"country_captain" | InstitutionType>("country_captain"); const [userId, setUserId] = useState(""); const [error, setError] = useState(""); async function assign() { try { if (!countryId || !userId.trim()) throw new Error("Choose a country and enter the registered user UUID."); await assignCompetitionRole({ competitionId: snapshot.competition.id, countryId, userId: userId.trim(), role, isCaptain: role === "country_captain" }); setUserId(""); await refresh(); } catch (caught) { setError(caught instanceof Error ? caught.message : "Role could not be assigned."); } } return <Card className="p-6"><p className="font-bold">Role adjustment</p><p className="mt-2 text-sm text-[var(--ink-muted)]">Use a registered user UUID to fill or replace an institution role. This is intentionally a director-only recovery control; normal participants self-claim in the Lobby.</p>{error && <div className="mt-3"><Notice error>{error}</Notice></div>}<div className="mt-4 grid gap-2 md:grid-cols-[1fr_1fr_1.5fr_auto]"><select value={countryId} onChange={(event) => setCountryId(event.target.value)} className="h-10 rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-2 text-xs">{snapshot.countries.map((country) => <option key={country.id} value={country.id}>{country.display_name}</option>)}</select><select value={role} onChange={(event) => setRole(event.target.value as typeof role)} className="h-10 rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-2 text-xs">{(["country_captain", ...roles] as const).map((item) => <option key={item} value={item}>{roleLabels[item]}</option>)}</select><input value={userId} onChange={(event) => setUserId(event.target.value)} placeholder="Registered user UUID" className="h-10 rounded-lg border border-[var(--line)] bg-[var(--canvas)] px-3 text-xs" /><Button onClick={() => void assign()}>Assign</Button></div><div className="mt-4 space-y-2">{snapshot.roles.filter((item) => item.country_id).map((item) => <div key={item.id} className="flex items-center justify-between rounded-lg bg-[var(--surface-subtle)] px-3 py-2 text-xs"><span>{snapshot.countries.find((country) => country.id === item.country_id)?.display_name} · <strong>{roleLabels[item.role_type as keyof typeof roleLabels] ?? item.role_type}</strong> · {item.profile?.display_name ?? item.user_id}</span><Button size="sm" variant="danger" onClick={() => { if (window.confirm("Remove this competition role?")) void removeCompetitionRole(item.id).then(refresh).catch((caught) => setError(caught instanceof Error ? caught.message : "Role could not be removed.")); }}>Remove</Button></div>)}</div></Card>; }
